<template>
  <section class="supply-network" aria-label="铀供应链供需网络">
    <div class="chain-tools">
      <el-input v-model="query" clearable placeholder="搜索国家、企业角色或供应链环节" aria-label="搜索供应链节点" class="node-search"><template #prefix><el-icon><Search/></el-icon></template></el-input>
      <div class="chain-key"><span><i class="blue"/>供应侧</span><span><i class="teal"/>连接与服务</span><span><i class="purple"/>需求侧</span></div>
      <span class="node-total">{{ query ? `${matches.size} 个匹配节点` : `${network?.nodes.length || 0} 个业务节点` }}</span>
      <button class="reset-link" @click="reset">重置视图</button>
    </div>
    <div v-if="error" class="chain-error" role="alert">{{ error }}<el-button text @click="load">重新加载</el-button></div>
    <div v-else v-loading="loading" class="board-scroll">
      <div ref="board" class="chain-board">
        <svg class="chain-links" :width="size.width" :height="size.height" aria-hidden="true"><defs><marker id="chain-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="currentColor"/></marker></defs><path v-for="edge in paths" :key="edge.id" :d="edge.path" :class="{focused:edge.focused,muted:focusId&&!edge.focused}" marker-end="url(#chain-arrow)"/></svg>
        <section v-for="zone in zones" :key="zone.id" class="chain-zone" :class="zone.id">
          <header class="zone-heading"><span class="zone-number">{{ zone.number }}</span><div><h3>{{ zone.title }}</h3><p>{{ zone.subtitle }}</p></div><span class="zone-count">{{ zoneNodes(zone.id).length }}</span></header>
          <div v-if="zone.id==='bridge'" class="bridge-stages"><div v-for="stage in stages" :key="stage.id" class="bridge-stage"><div class="stage-label">{{ stage.label }}<span>→</span></div><div class="stage-nodes"><button v-for="node in zoneNodes(zone.id).filter(n=>n.stage===stage.id)" :key="node.id" :data-chain-node="node.id" class="chain-node" :class="nodeClass(node)" @mouseenter="hoverId=node.id" @mouseleave="hoverId=''" @focus="hoverId=node.id" @blur="hoverId=''" @click="inspect(node.id)"><span class="node-top"><span class="node-code">{{ node.code }}</span><span class="node-open">↗</span></span><strong>{{ node.name }}</strong><small>{{ node.subtitle }}</small></button></div></div></div>
          <div v-else class="zone-nodes"><button v-for="node in zoneNodes(zone.id)" :key="node.id" :data-chain-node="node.id" class="chain-node" :class="nodeClass(node)" @mouseenter="hoverId=node.id" @mouseleave="hoverId=''" @focus="hoverId=node.id" @blur="hoverId=''" @click="inspect(node.id)"><span class="node-top"><span class="node-code">{{ node.code }}</span><span class="node-open">↗</span></span><strong>{{ node.name }}</strong><small>{{ node.subtitle }}</small><span v-if="node.verification" class="evidence-label">{{ verificationLabel(node.verification) }}</span></button></div>
        </section>
      </div>
    </div>
    <div class="chain-caption"><span><i/>{{ network?.edge_note || '连线表示供应链环节及前后级关系。' }}</span><span>悬停高亮关联 · 点击打开节点档案</span></div>
    <section class="external-events"><header><div><span class="event-mark">!</span><h3>外部事件与供应链冲击</h3><p>政策、生产和运输事件，沿关联环节传导</p></div><span>事件档案 ↘</span></header><div class="event-grid"><button v-for="(event,i) in network?.events || []" :key="event.id" @click="inspect(event.id)"><span class="event-index">0{{ i+1 }}</span><div><strong>{{ event.name }}</strong><small>{{ event.subtitle }}</small></div><span class="event-arrow">↗</span></button></div></section>
    <UraniumNodeArchive v-model:open="archiveOpen" :node-id="selectedId" :network="network" :initial-section="initialSection" @navigate="inspect"/>
  </section>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Search } from '@element-plus/icons-vue'
import { getUraniumDomainNetwork } from '@/api/uraniumDomainArchive'
import UraniumNodeArchive from '@/components/SCnet/UraniumNodeArchive.vue'
defineProps({model:{type:Object,required:true},rows:{type:Array,default:()=>[]},instance:{type:Object,default:null}})
const network=ref(null),loading=ref(true),error=ref(''),query=ref(''),selectedId=ref(''),hoverId=ref(''),archiveOpen=ref(false),initialSection=ref('overview'),board=ref(null)
const positions=ref({}),size=ref({width:1200,height:650})
const zones=[{id:'supply',number:'01',title:'供应侧',subtitle:'资源国家与国内供应'},{id:'bridge',number:'02',title:'连接与服务',subtitle:'把供给组织为可交付的供应链'},{id:'demand',number:'03',title:'需求侧',subtitle:'采购、燃料使用与供应保障'}]
const stages=[{id:1,label:'交易与协同'},{id:2,label:'运输与仓储'},{id:3,label:'加工与监管'}]
const zoneNodes=id=>(network.value?.nodes||[]).filter(n=>n.zone===id)
const matches=computed(()=>new Set((network.value?.nodes||[]).filter(n=>`${n.name} ${n.subtitle} ${n.code} ${n.kind}`.toLowerCase().includes(query.value.trim().toLowerCase())).map(n=>n.id)))
const focusId=computed(()=>hoverId.value || (archiveOpen.value?selectedId.value:''))
const adjacent=computed(()=>new Set((network.value?.edges||[]).filter(e=>e.source===focusId.value||e.target===focusId.value).flatMap(e=>[e.source,e.target])))
const nodeClass=n=>({selected:n.id===focusId.value,related:adjacent.value.has(n.id),faded:query.value.trim()&&!matches.value.has(n.id),'china-node':n.id==='china'})
const verificationLabel=status=>({direct_historical:'有历史对华交付依据',shipment_historical:'有历史对华启运记录',contract_only:'有对华合同依据',not_verified:'铀生产国资料',customs_and_services:'有海关记录 · 燃料服务',service_only:'核燃料服务资料',materials_historical:'有历史核材料转移记录',trace_observation:'有微量海关记录',disputed_observation:'有海关记录 · 口径差异'}[status]||'公开来源资料')
const paths=computed(()=>(network.value?.edges||[]).flatMap(e=>{
  const a=positions.value[e.source],b=positions.value[e.target];if(!a||!b)return []
  let path
  if(Math.abs(a.cx-b.cx)<60){const x=Math.max(a.right,b.right)+14;path=`M${a.right},${a.cy} C${x},${a.cy} ${x},${b.cy} ${b.right},${b.cy}`}
  else {const forward=b.cx>a.cx,x1=forward?a.right:a.left,x2=forward?b.left:b.right,dx=Math.abs(x2-x1)*.48;path=`M${x1},${a.cy} C${x1+(forward?dx:-dx)},${a.cy} ${x2-(forward?dx:-dx)},${b.cy} ${x2},${b.cy}`}
  return [{...e,path,focused:focusId.value&&(e.source===focusId.value||e.target===focusId.value)}]
}))
let observer,frame
function measure(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(!board.value)return;const base=board.value.getBoundingClientRect(),p={};for(const el of board.value.querySelectorAll('[data-chain-node]')){const r=el.getBoundingClientRect();p[el.dataset.chainNode]={left:r.left-base.left,right:r.right-base.left,cy:r.top-base.top+r.height/2,cx:r.left-base.left+r.width/2}}positions.value=p;size.value={width:board.value.scrollWidth,height:board.value.scrollHeight}})}
function inspect(id,section='overview'){initialSection.value=section;selectedId.value=id;archiveOpen.value=true}
function reset(){query.value='';hoverId.value='';archiveOpen.value=false;selectedId.value='';board.value?.parentElement.scrollTo({left:0,behavior:'smooth'})}
async function load(){loading.value=true;error.value='';try{network.value=await getUraniumDomainNetwork();await nextTick();measure()}catch{error.value='供需网络暂时无法加载，请检查服务连接后重试。'}finally{loading.value=false}}
onMounted(async()=>{await load();observer=new ResizeObserver(measure);if(board.value)observer.observe(board.value)})
watch(network,()=>nextTick(measure))
onBeforeUnmount(()=>{observer?.disconnect();cancelAnimationFrame(frame)})
</script>

<style scoped>
