om:1px solid var(--zone-border);border-radius:6px 6px 0 0}.zone-number{display:grid;place-items:center;width:28px;height:28px;flex-shrink:0;box-sizing:border-box;font-size:12px;font-weight:750;color:#fff;background:var(--zone-accent);border-radius:6px}.zone-heading h3{font-size:16px;margin:1px 0 7px;font-weight:750;color:#1f568f}.bridge .zone-heading h3{color:#086a58}.demand .zone-heading h3{color:#63408f}.zone-heading p{font-size:10px;color:#526b83;margin:0;line-height:1.5}.bridge .zone-heading p{color:#456e60}.demand .zone-heading p{color:#746188}.zone-count{margin-left:auto;display:grid;place-items:center;min-width:24px;height:24px;padding:0 6px;box-sizing:border-box;border:1px solid var(--zone-border);border-radius:12px;background:#ffffffb3;color:var(--zone-accent);font-size:11px;font-weight:650}.zone-nodes{display:flex;flex-direction:column;gap:12px}.chain-node{position:relative;z-index:2;display:flex;flex-direction:column;width:100%;min-height:83px;padding:12px 13px;box-sizing:border-box;border:1px solid #dce5ef;border-radius:7px;background:#fff;box-shadow:0 2px 4px #29435d04;text-align:left;cursor:pointer;transition:border-color .2s,box-shadow .2s,opacity .2s}.chain-node:hover,.chain-node.selected{border-color:#2f85cf;box-shadow:0 0 0 3px #388ada10}.bridge .chain-node:hover,.bridge .chain-node.selected{border-color:#32a18e;box-shadow:0 0 0 3px #2b9e8d10}.demand .chain-node:hover,.demand .chain-node.selected{border-color:#9276c3;box-shadow:0 0 0 3px #9276c310}.node-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.node-code{font-size:9px;font-weight:650;letter-spacing:1px;color:#7899b6}.bridge .node-code{color:#60a090}.demand .node-code{color:#a08bb8}.node-open{font-size:12px;color:#b2bfd0}.chain-node>strong{font-size:13px;font-weight:600;line-height:1.45;color:#314963}.chain-node>small{font-size:10px;line-height:1.6;color:#8b99a9;margin-top:5px}.chain-node.faded{opacity:.25}.evidence-label{display:inline-flex;margin-top:8px;color:#6f8b82;font-size:9px;line-height:1.4}.supply .zone-nodes{display:grid;grid-template-columns:1fr 1fr;gap:12px}.supply .chain-node{min-height:115px;padding:12px 10px}.supply .chain-node>strong{font-size:12px}.bridge-stages{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;padding-top:10px}.stage-label{position:relative;z-index:2;font-size:10px;font-weight:600;color:#397b68;padding:0 2px;margin-bottom:18px;display:flex;justify-content:space-between}.stage-label>span{color:#99b9b3}.stage-nodes{display:flex;flex-direction:column;gap:70px}.bridge-stage:nth-child(2){padding-top:45px}.bridge-stage:nth-child(3){padding-top:90px}.supply .chain-node{border-color:#bed2ed}.bridge .chain-node{min-height:95px;border-color:#a9cfbf}.demand .chain-node{border-color:#cdb9e4}.demand .zone-nodes{gap:16px}.china-node{border-color:#cebfe6;background:#faf7ff;min-height:96px}.china-node>strong{font-size:15px}.chain-caption{display:flex;justify-content:space-between;gap:20px;padding:14px 28px;font-size:10px;color:#8594a7;line-height:1.7}.chain-caption>span:first-child{display:flex;gap:7px;align-items:center}.chain-caption i{height:5px;width:5px;border-radius:50%;background:#94a9bf;flex-shrink:0}.external-events{padding:6px 28px 27px}.external-events>header,.external-events>header>div{display:flex;align-items:center;gap:9px}.external-events>header{justify-content:space-between;margin-bottom:14px}.external-events h3{font-size:13px;font-weight:600;margin:0;color:#49576b}.external-events p,.external-events>header>span{font-size:10px;color:#9b9ba5;margin:0}.event-mark{color:#b88c4b;background:#fcf3df;font-size:10px;font-weight:bold;width:18px;height:18px;display:grid;place-items:center;border-radius:5px}.event-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.event-grid button{display:flex;align-items:center;gap:10px;border:1px solid #eee7dc;border-radius:8px;background:#fffdf9;padding:16px 13px;text-align:left;cursor:pointer}.event-grid button:hover{background:#fff8ec;border-color:#dcc3a0}.event-index{font-size:10px;color:#bca788;align-self:flex-start;padding-top:2px}.event-grid strong{font-size:12px;color:#766249;font-weight:550}.event-grid small{display:block;font-size:10px;color:#a99e90;margin-top:7px;line-height:1.5}.event-arrow{margin-left:auto;color:#baaa93}.chain-error{padding:50px;text-align:center;color:#9f5656;font-size:13px}@media(min-width:1550px){.chain-board{grid-template-columns:minmax(260px,1.15fr) minmax(650px,2.7fr) minmax(220px,.95fr)}.supply .chain-node{min-height:115px}}@media(max-width:1000px){.chain-tools{margin:0 20px;gap:14px}.chain-key{display:none}.chain-caption{padding:12px 20px}.chain-caption>span:last-child{display:none}.external-events{padding:6px 20px 20px}.event-grid{grid-template-columns:repeat(2,1fr)}.external-events p{display:none}}@media(max-width:640px){.node-search{width:100%}.node-total{display:none}.reset-link{white-space:nowrap}.external-events>header>span{display:none}.event-grid button{padding:12px 9px}}
</style>
